// Valida el trabajo que entregó el CRM. Solo se acepta un trabajo de motor "mora"
// con autorización temporal (lease) y el rol que el CRM tomó de la sesión.
const r = $input.first().json.value;
const jobs = r?.job;
if (Array.isArray(jobs) && jobs.length !== 1) throw Error('Se esperaba exactamente una consulta M.O.R.A');
const job = Array.isArray(jobs) ? jobs[0] : jobs;
const required = ['id', 'engine', 'lease_token', 'evaluation_id', 'thread_id', 'actor_uid', 'actor_role', 'question'];
if (r?.ok !== true || !job || required.some(k => typeof job[k] !== 'string' || !job[k].trim())) {
  throw Error('El CRM no entregó una consulta M.O.R.A válida');
}
if (job.engine !== 'mora') throw Error('Trabajo de otro motor; M.O.R.A no lo procesa');
if (!['Gerente', 'Vendedor', 'Broker'].includes(job.actor_role)) throw Error('Rol no reconocido por M.O.R.A');
if (!/^[a-zA-Z0-9_-]{1,100}$/.test(job.id) || !/^[a-zA-Z0-9_-]{1,100}$/.test(job.evaluation_id)) {
  throw Error('Identificadores de consulta no válidos');
}
return [{
  json: {
    id: job.id,
    engine: 'mora',
    lease_token: job.lease_token,
    evaluation_id: job.evaluation_id,
    thread_id: job.thread_id,
    actor_uid: job.actor_uid,
    actor_role: job.actor_role,
    question: job.question.trim().slice(0, 2000),
    tier: ['quick', 'default', 'complex'].includes(job.tier) ? job.tier : 'default',
    view: String(job.view || 'indicadores').slice(0, 40)
  }
}];

// El alcance lo decide PostgreSQL con el rol congelado del CRM:
//  - "completo": Gerencia o editor asignado a esa evaluación.
//  - "resumen": cualquier otro rol; solo avance comercial y de obra, sin cifras financieras.
// Aquí se vuelve a comprobar (defensa en profundidad): el bloqueo vive en los datos.
const j = $('Conservar consulta M.O.R.A').first().json;
const r = $input.first().json.value;
if (!r?.ok || r.job_id !== j.id || !['completo', 'resumen'].includes(r.scope) || !r.evaluation || !Array.isArray(r.history)) {
  throw Error('No se recuperó el contexto autorizado de la consulta');
}
if (r.scope === 'resumen' && (r.evaluation.analysis || r.evaluation.inputs)) {
  throw Error('El contexto de alcance resumen trajo datos restringidos; se detiene la consulta');
}
if (r.scope === 'completo' && (!r.evaluation.inputs?.p || !Array.isArray(r.evaluation.inputs?.units))) {
  throw Error('La evaluación no trae los insumos del motor (inputs.p y inputs.units)');
}
return [{
  json: {
    ...j,
    scope: r.scope,
    evaluation: r.evaluation,
    history: r.history.slice(-12).map(h => ({ role: h.role === 'assistant' ? 'assistant' : 'user', text: String(h.text || '').slice(0, 1200) })),
    memory: r.memory || {}, drive_context:r.scope==='completo'?j.drive_context:null
  }
}];

// Primer paso con un modelo rápido: entender qué pide la persona y, si corresponde,
// traducirlo a escenarios numéricos que el motor determinista calculará.
const c = $input.first().json;
const KEYS = {
  precioM2: 'precio de venta por m² con IGV (S/)',
  costoM2: 'costo de construcción por m² sin IGV (S/)',
  precioTerrenoM2: 'precio del terreno por m² (S/)',
  velocidad: 'velocidad de venta (unidades/mes)',
  descProm: 'descuento promedio (%)',
  mesLanz: 'mes de lanzamiento comercial',
  inicioObra: 'mes de inicio de obra',
  durObra: 'duración de obra (meses)',
  inicial: 'cuota inicial (%)',
  financiaPct: 'financiamiento bancario (% de construcción)',
  preventaMin: 'preventa mínima para desembolso (%)',
  tea: 'TEA del crédito promotor (%)',
  contingencia: 'contingencia (% de construcción)',
  tasaDesc: 'tasa de descuento anual (%)'
};
const p = c.scope === 'completo' ? c.evaluation.inputs.p : null;
const actuales = p ? Object.fromEntries(Object.keys(KEYS).map(k => [k, p[k]])) : null;
const SYSTEM = `Clasificas consultas internas para M.O.R.A (Motor de Optimización, Riesgo y Análisis), la agente del Evaluador Inmobiliario de una desarrolladora en Lima.
Responde SOLO con un objeto JSON, sin texto adicional:
{"intent":"consulta|simulacion|propuesta_cambio|seguimiento|fuera_de_alcance","needs_full_scope":true|false,"scenarios":[{"name":"texto corto","changes":{"clave":numero}}]}
- consulta: pide explicar o interpretar cifras existentes.
- simulacion: pide "qué pasa si", comparar o encontrar un valor (por ejemplo el precio para un margen meta).
- propuesta_cambio: pide ajustar supuestos o la estrategia (quedará pendiente de aprobación de Gerencia).
- seguimiento: pregunta por avance real frente a la línea base.
- fuera_de_alcance: temas ajenos a la evaluación del proyecto (por ejemplo atender a un cliente, que es tarea de L.O.L.A en el CRM).
needs_full_scope es true si responder exige márgenes, costos, utilidad, TIR, VAN, flujo, aporte o supuestos financieros.
Escenarios: máximo 4, solo cuando haya que calcular. Claves permitidas: ${Object.entries(KEYS).map(([k, v]) => k + ' (' + v + ')').join('; ')}.
Para buscar un valor meta, propone 3 o 4 escenarios que lo encierren (por ejemplo varios precios). Usa los valores actuales como referencia.`;
const user = JSON.stringify({ pregunta: c.question, pestana: c.view, alcance: c.scope, supuestos_actuales: actuales, historial_reciente: c.history.slice(-4) });
return [{ json: { payload: { model: 'claude-haiku-5-5', max_tokens: 700, system: SYSTEM, messages: [{ role: 'user', content: user }] } } }];

// Nunca se confía en la salida del modelo: el plan se valida contra una lista cerrada
// de claves y rangos. Si el clasificador falla, M.O.R.A responde sin simular.
const c = $('Aplicar alcance de permisos').first().json;
const res = $input.first().json;
const textOf = r => (r && !r.error && Array.isArray(r.content)) ? r.content.filter(x => x.type === 'text').map(x => x.text).join('\n') : '';
const parse = t => { if (!t) return null; try { return JSON.parse(t); } catch {} const m = t.match(/\{[\s\S]*\}/); if (m) { try { return JSON.parse(m[0]); } catch {} } return null; };
// Rangos absolutos razonables; además, cada cambio debe quedar entre 40% y 250% del valor actual.
const LIM = {
  precioM2: [1500, 30000], costoM2: [800, 12000], precioTerrenoM2: [300, 25000], velocidad: [0.1, 6], descProm: [0, 25],
  mesLanz: [0, 36], inicioObra: [0, 36], durObra: [6, 36], inicial: [5, 60], financiaPct: [0, 90], preventaMin: [0, 80],
  tea: [3, 30], contingencia: [0, 10], tasaDesc: [4, 30]
};
const INTENTS = ['consulta', 'simulacion', 'propuesta_cambio', 'seguimiento', 'fuera_de_alcance'];
const raw = parse(textOf(res));
let intent = INTENTS.includes(raw?.intent) ? raw.intent : 'consulta';
const p = c.scope === 'completo' ? c.evaluation.inputs.p : {};
let scenarios = [];
if (c.scope === 'completo' && Array.isArray(raw?.scenarios)) {
  for (const sc of raw.scenarios.slice(0, 4)) {
    const changes = {};
    for (const [k, v] of Object.entries(sc?.changes || {})) {
      const n = Number(v);
      if (!LIM[k] || !Number.isFinite(n) || n < LIM[k][0] || n > LIM[k][1]) continue;
      const cur = Number(p[k]);
      if (Number.isFinite(cur) && cur > 0 && (n < cur * 0.4 || n > cur * 2.5)) continue;
      changes[k] = Math.round(n * 1000) / 1000;
    }
    if (Object.keys(changes).length) scenarios.push({ name: String(sc.name || 'Escenario').slice(0, 60), changes });
  }
}
if (c.scope === 'resumen' && raw?.needs_full_scope === true) intent = 'fuera_de_permiso';
return [{ json: { ...c, plan: { intent, scenarios, classifier_ok: !!raw, classifier_usage: res?.usage || null } } }];

// Motor M.O.R.A: el MISMO cálculo del Evaluador Inmobiliario (perfil, IGV, flujo mensual,
// crédito promotor, IR, TIR y VAN). Las cifras de cada escenario salen de aquí, no del modelo.
const CATS=['Terreno','Construcción','Contingencias','Inmobiliarios','Financieros','Legales','Marketing','Ventas','Posventa'];
const BENCH={Terreno:[20,30],'Construcción':[50,65],Contingencias:[2,3],Inmobiliarios:[8,12],Financieros:[1,2],Legales:[0.5,1],Marketing:[2.5,4],Ventas:[2,3.5],Posventa:[1,1.5]};
const DRV={m2terreno:'m² terreno',m2techada:'m² techados',unidades:'unidades',mesesObra:'meses de obra',mesesProyecto:'meses de proyecto',anios:'años',global:'global',manual:'cantidad manual',pctVentas:'% de ventas',pctConstr:'% de construcción',predial:'predial (tramos UIT)'};
const GCAT={inm:'Inmobiliarios',leg:'Legales',fin:'Financieros'};
const sum=a=>a.reduce((x,y)=>x+(+y||0),0);

function calcPredial(av,uit){
  const t=[[15*uit,0.002],[60*uit,0.006],[Infinity,0.01]];let prev=0,tot=0;const rows=[];
  for(const [lim,r] of t){const base=Math.max(0,Math.min(av,lim)-prev);rows.push({desde:prev,hasta:lim,base,r,imp:base*r});tot+=base*r;prev=lim;if(av<=lim)break}
  return {rows,total:tot};
}
function obraCurve(parts,N){
  const tw=sum(parts.map(x=>x.pct))||1;const out=new Array(N).fill(0);
  for(const pt of parts){const c=pt.c,M=c.length,tc=sum(c)||1;const C=[0];c.forEach(v=>C.push(C[C.length-1]+v/tc));
    const at=x=>{const i=Math.min(M-1,Math.floor(x));const f=x-i;return C[i]+(C[i+1]-C[i])*f};
    for(let j=0;j<N;j++){out[j]+=(at(M*(j+1)/N)-at(M*j/N))*pt.pct/tw}}
  return out;
}
function partCurves(parts,N){
  return parts.map(pt=>{const c=pt.c,M=c.length,tc=sum(c)||1;const C=[0];c.forEach(v=>C.push(C[C.length-1]+v/tc));
    const at=x=>{const i=Math.min(M-1,Math.floor(x));const f=x-i;return C[i]+(C[i+1]-C[i])*f};
    return Array.from({length:N},(_,j)=>at(M*(j+1)/N)-at(M*j/N))});
}
function irr(cf){
  const npv=r=>cf.reduce((a,v,i)=>a+v/Math.pow(1+r,i),0);
  if(!cf.some(v=>v<0)||!cf.some(v=>v>0))return null;
  let lo=null,hi=null,flo,fhi,prev=-0.05,fp=npv(prev);
  for(let r=-0.049;r<=0.6;r+=0.001){const f=npv(r);if(fp*f<=0){lo=prev;hi=r;flo=fp;fhi=f;break}prev=r;fp=f}
  if(lo===null)return null;
  for(let k=0;k<200;k++){const m=(lo+hi)/2,fm=npv(m);if(flo*fm<=0){hi=m;fhi=fm}else{lo=m;flo=fm}}
  return (lo+hi)/2;
}
const npvM=(cf,anual)=>{const r=Math.pow(1+anual,1/12)-1;return cf.reduce((a,v,i)=>a+v/Math.pow(1+r,i),0)};

function compute(s,ov){
  const p=Object.assign({},s.p,ov||{});
  const nU=s.units.length||1;
  const techV=sum(s.units.map(u=>u.tech)), libreV=sum(s.units.map(u=>u.libre));
  const areaTech=techV+(+p.comunTechada||0);
  const igvEf=p.igv/100*p.baseGravada/100;
  const units=s.units.map(u=>{const lista=((+u.tech||0)+(+u.libre||0)*p.factorLibre)*p.precioM2*(1+(+u.aj||0)/100);return {...u,lista,neto:lista*(1-p.descProm/100)}});
  const vDept=sum(units.map(u=>u.neto)), vEst=p.nEstac*p.precioEstac*(1-p.descProm/100);
  const plan=Array.isArray(p.plan)?p.plan.map(x=>({t:Math.max(0,Math.round(+x.t||0)),v:+x.v||0})):null;
  const vDeptR=plan?sum(plan.map(x=>x.v)):vDept;
  const ventas=vDeptR+vEst, ventasSin=ventas/(1+igvEf), igvVentas=ventas-ventasSin;
  const io=+p.inicioObra, dur=Math.max(1,Math.round(+p.durObra)), ent=io+dur, ind=Math.max(1,Math.round(+p.indep));
  const lanz=+p.mesLanz, vel=Math.max(0.05,+p.velocidad);
  const finVentas=plan&&plan.length?Math.max(...plan.map(x=>x.t)):lanz+Math.ceil(nU/vel-1e-9)-1;
  const H=Math.max(ent+ind+3,finVentas+3,ent+12);
  const anios=Math.ceil((ent+ind)/12);
  const pred=calcPredial(+p.autovaluo,+p.uit);
  const constrSub=areaTech*p.costoM2;
  const cd=constrSub/(1+p.ggPct/100+p.utilPct/100);
  const curve=obraCurve(s.part,dur);
  // ventas y cobranzas
  const avg=ventas/nU, sold=new Array(H+1).fill(0), cobro=new Array(H+1).fill(0), soldCum=new Array(H+1).fill(0);
  const valT=new Array(H+1).fill(0);let c=0;
  if(plan){for(const x of plan){const t=Math.min(H,x.t);sold[t]+=1;valT[t]+=x.v+vEst/nU}}
  else{for(let t=lanz;t<=H&&c<nU-1e-9;t++){const a=Math.min(vel,nU-c);sold[t]=a;c+=a}for(let t=0;t<=H;t++)valT[t]=sold[t]*avg}
  c=0;for(let t=0;t<=H;t++){c+=sold[t];soldCum[t]=c/nU}
  const ini=p.inicial/100;let pend=0;
  for(let t=0;t<=H;t++){const v=valT[t];if(!v)continue;if(t<ent){cobro[t]+=v*ini;pend+=v*(1-ini)}else{cobro[t]+=v*ini;cobro[Math.min(H,t+1)]+=v*(1-ini)}}
  for(let k=0;k<ind;k++)cobro[Math.min(H,ent+k)]+=pend/ind;
  const sumCobro=sum(cobro)||1;
  const weights=(pago)=>{const a=new Array(H+1).fill(0);const P=String(pago==null?'':pago).trim().toLowerCase();
    const even=(x,y)=>{const a1=Math.max(0,Math.min(H,x)),b1=Math.max(a1,Math.min(H,y));const n=b1-a1+1;for(let i=a1;i<=b1;i++)a[i]+=1/n};
    if(P==='curva'){curve.forEach((v,i)=>{a[Math.min(H,io+i)]+=v});return a}
    if(P==='obra'){even(io,ent-1);return a}
    if(P==='proyecto'){even(0,ent+ind-1);return a}
    if(P==='diseño'||P==='diseno'){even(0,io-1);return a}
    if(P==='ventas'){even(lanz-1,finVentas);return a}
    if(P==='entrega'){a[Math.min(H,ent)]=1;return a}
    if(P==='independizacion'||P==='independización'){even(ent,ent+ind-1);return a}
    if(P==='posventa'){even(ent,ent+11);return a}
    if(P==='cierre'){a[H]=1;return a}
    if(P==='banco'){a[Math.min(H,io)]=1;return a}
    if(P==='cobros'){cobro.forEach((v,i)=>a[i]=v/sumCobro);return a}
    if(P.includes(':')){P.split(',').forEach(x=>{const [m,pc]=x.split(':').map(Number);if(!isNaN(m))a[Math.min(H,Math.max(0,Math.round(m)))]+=(+pc||0)});const t=sum(a);if(t>0)for(let i=0;i<=H;i++)a[i]/=t;else a[0]=1;return a}
    if(/^\d+\s*-\s*\d+$/.test(P)){const [x,y]=P.split('-').map(Number);even(x,y);return a}
    const m=Number(P);if(P!==''&&!isNaN(m)){a[Math.min(H,Math.max(0,Math.round(m)))]=1;return a}
    even(0,H);return a};
  // partidas de egreso
  const L=[];
  const add=(cat,n,sub,igvOn,pago,x)=>{const igv=igvOn?sub*p.igv/100:0;const o=Object.assign({cat,n,sub,igv,tot:sub+igv,pago},x||{});o.m=weights(pago).map(w=>w*o.tot);o.mi=weights(pago).map(w=>w*o.igv);L.push(o);return o};
  const terr=p.areaTerreno*p.precioTerrenoM2;
  add('Terreno','Terreno',terr,false,'0',{q:p.areaTerreno,u:'m²',pu:p.precioTerrenoM2});
  add('Terreno','Alcabala',Math.max(0,terr-10*p.uit)*p.alcabala/100,false,'0',{q:Math.max(0,terr-10*p.uit),u:'base',pu:p.alcabala,pct:true});
  add('Construcción','Construcción (CD + GG + utilidad)',constrSub,true,'curva',{q:areaTech,u:'m²',pu:p.costoM2,key:'constr'});
  add('Construcción','Supervisión de obra',areaTech*p.supervisionM2,true,'curva',{q:areaTech,u:'m²',pu:p.supervisionM2,key:'constr'});
  add('Contingencias','Manejo de vecinos y comunidad',constrSub*p.contingencia/100,true,'obra',{q:constrSub,u:'base',pu:p.contingencia,pct:true});
  const qty=(it)=>({m2terreno:p.areaTerreno,m2techada:areaTech,unidades:nU,mesesObra:dur,mesesProyecto:ent+ind,global:1,anios,pctVentas:ventas,pctConstr:constrSub,predial:anios,manual:+it.q||0})[it.d]??1;
  for(const g of ['inm','leg','fin','com'])s[g].forEach((it,i)=>{const q=qty(it);const pct=String(it.d).startsWith('pct');const pu=it.d==='predial'?pred.total:+it.pu||0;
    add(it.cat||GCAT[g],it.n,pct?q*pu/100:q*pu,!!it.igv,it.pago,{q,u:DRV[it.d],pu,pct,g,i})});
  const E=new Array(H+1).fill(0),Efin=new Array(H+1).fill(0),igvC=new Array(H+1).fill(0),constrM=new Array(H+1).fill(0);
  const byCat={};CATS.forEach(k=>byCat[k]=new Array(H+1).fill(0));
  for(const o of L){for(let t=0;t<=H;t++){E[t]+=o.m[t];igvC[t]+=o.mi[t]*p.prorrata/100;(byCat[o.cat]||(byCat[o.cat]=new Array(H+1).fill(0)))[t]+=o.m[t];if(o.cat==='Financieros')Efin[t]+=o.m[t];if(o.key==='constr')constrM[t]+=o.m[t]}}
  const igvD=cobro.map(v=>v*igvEf/(1+igvEf));
  const det=cobro.map(v=>p.detracOn?v*p.detraccion/100:0), detRel=new Array(H+1).fill(0);
  det.forEach((v,t)=>{detRel[Math.min(H,Math.max(t,ent+ind+1))]+=v});
  const constrTot=sum(L.filter(o=>o.key==='constr').map(o=>o.tot));
  const bankLim=p.bancoOn?constrTot*p.financiaPct/100:0, rM=Math.pow(1+p.tea/100,1/12)-1;
  const run=(irPay)=>{
    const R={aporte:[],dist:[],draw:[],amort:[],intr:[],igvPay:[],bankBal:[],cash:[],credit:[]};
    for(const k in R)R[k]=new Array(H+1).fill(0);
    let cash=0,bank=0,drawn=0,credit=0,bankStart=null;
    const future=new Array(H+2).fill(0);for(let t=H;t>=0;t--)future[t]=future[t+1]+E[t];
    for(let t=0;t<=H;t++){
      credit+=igvC[t];const pay=Math.max(0,igvD[t]-credit);credit=Math.max(0,credit-igvD[t]);R.igvPay[t]=pay;R.credit[t]=credit;
      const it=bank*rM;R.intr[t]=it;
      cash+=cobro[t]-det[t]+detRel[t]-E[t]-pay-it-(t===H?irPay:0);
      if(bank>0&&t>=ent&&cash>0){const a=Math.min(bank,cash);bank-=a;cash-=a;R.amort[t]=a}
      const elig=p.bancoOn&&t>=io&&t<ent&&soldCum[t]>=p.preventaMin/100-1e-9;
      if(elig&&bankStart===null)bankStart=t;
      if(cash<0&&elig){const d=Math.min(-cash,constrM[t],bankLim-drawn);if(d>0){bank+=d;drawn+=d;cash+=d;R.draw[t]=d}}
      if(cash<0){R.aporte[t]=-cash;cash=0}
      if(t===H){R.dist[t]=cash;cash=0}
      else if(t>=ent&&bank<=1e-6&&cash>0){const need=future[t+1]+irPay*1.0;const d=Math.max(0,cash-need);if(d>0){R.dist[t]=d;cash-=d}}
      R.bankBal[t]=bank;R.cash[t]=cash;
    }
    R.bankStart=bankStart;R.drawn=drawn;R.bankEnd=bank;return R};
  let F=run(0);
  const intTot=sum(F.intr), igvPagado=sum(F.igvPay);
  const egresos=sum(L.map(o=>o.tot))+intTot;
  const uai=ventas-egresos-igvPagado;
  const irAmt=Math.max(0,uai)*p.ir/100;
  F=run(irAmt);
  const intTot2=sum(F.intr);
  const egresosF=sum(L.map(o=>o.tot))+intTot2;
  const uaiF=ventas-egresosF-sum(F.igvPay);
  const irF=Math.max(0,uaiF)*p.ir/100, neta=uaiF-irF;
  const econ=[],eq=[];
  for(let t=0;t<=H;t++){econ.push(cobro[t]-det[t]+detRel[t]-(E[t]-Efin[t])-F.igvPay[t]-(t===H?irF:0));eq.push(F.dist[t]-F.aporte[t])}
  let cum=0,peak=0;for(let t=0;t<=H;t++){cum+=F.aporte[t]-F.dist[t];peak=Math.max(peak,cum)}
  let cumE=0,peakE=0,payback=null;for(let t=0;t<=H;t++){cumE+=econ[t];peakE=Math.min(peakE,cumE);if(payback===null&&t>0&&cumE>=0&&peakE<0)payback=t}
  const ie=irr(econ),iq=irr(eq);
  const groups={};CATS.forEach(k=>groups[k]={sub:0,igv:0,tot:0});
  L.forEach(o=>{const g=groups[o.cat]||(groups[o.cat]={sub:0,igv:0,tot:0});g.sub+=o.sub;g.igv+=o.igv;g.tot+=o.tot});
  groups['Financieros'].tot+=intTot2;groups['Financieros'].sub+=intTot2;
